/* ----------------------------- Bundled Study Module registry ----------------------------- */
/*
 Android file providers expose local HTML through content:// URIs. A page opened from one
 content URI cannot reliably navigate to a sibling HTML file by relative filename. To keep
 the Main Base -> Study Module integration reliable on phones/tablets, Chapter 25 is stored
 as a self-contained HTML Blob in IndexedDB and launched through an object URL. The module
 remains logically independent: the Main Base owns only its manifest/summary/launch record.
*/
const BUNDLED_MODULES=Object.freeze([{
 moduleId:'pharmacology-ch25-diabetes',
 subjectId:'phbiosci-33',
 title:'Chapter 25 — Drugs for Diabetes',
 subtitle:'Interactive Study Module',
 version:'shared-study-refinement-1',
 schemaVersion:1,
 moduleType:'bundled-html',
 capabilities:['reader','annotations','studyGuide','activeRecall','mcq','tables','compare','notes','progress','weakTopics'],
 status:'READY',
 fileName:'Chapter25_Diabetes_Interactive_StudyGuide_ProAnnotations.html',
 bundledBase64:''
},{moduleId:'hospital-pharmacy-midterms',subjectId:'pharma-32',title:'Hospital Pharmacy — Midterms',subtitle:'Study guide, MCQ, flashcards and adaptive mastery',version:'shared-study-refinement-1',schemaVersion:1,moduleType:'bundled-html',capabilities:['reader','annotations','studyGuide','activeRecall','mcq','flashcards','tables','notes','progress','weakTopics'],status:'READY',fileName:'Hospital_Pharmacy_Midterms.html',bundledBase64:''}]);
const STORES=['subjects','chapters','topics','modules','materials','notes','calendarNotes','annotations','flashcardSets','flashcards','quizSets','questions','tables','progress','shares','trash','meta'];
const uid=(p='id')=>`${p}_${(crypto.randomUUID?crypto.randomUUID():Math.random().toString(36).slice(2)+Date.now())}`;
const now=()=>new Date().toISOString();
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmtDate=s=>s?new Date(s).toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'';
const pad2=n=>String(n).padStart(2,'0');
const dateKey=(y,m,d)=>`${y}-${pad2(m)}-${pad2(d)}`;
const todayKey=()=>{const d=new Date();return dateKey(d.getFullYear(),d.getMonth()+1,d.getDate())};
const parseDateKey=k=>{const [y,m,d]=String(k||'').split('-').map(Number);return new Date(y||1970,(m||1)-1,d||1,12,0,0)};
const formatDay=k=>parseDateKey(k).toLocaleDateString([], {weekday:'long',month:'long',day:'numeric',year:'numeric'});
const formatMonth=(y,m)=>new Date(y,m,1,12).toLocaleDateString([], {month:'long',year:'numeric'});
const byUpdated=(a,b)=>new Date(b.updatedAt||b.createdAt||0)-new Date(a.updatedAt||a.createdAt||0);

/* ----------------------------- Storage layer ----------------------------- */
const Storage={
 db:null,
 async init(){
  this.db=await new Promise((resolve,reject)=>{const r=indexedDB.open('PersonalStudyLibrary',3);r.onupgradeneeded=()=>{const db=r.result;for(const s of STORES)if(!db.objectStoreNames.contains(s))db.createObjectStore(s,{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>{const main=document.getElementById('main');if(main)main.innerHTML='<div class=card><h2>Storage is waiting</h2><p>Close older copies of Study Library, then reopen this page. Saved data has not been cleared.</p></div>'};});
 },
 store(name,mode='readonly'){return this.db.transaction(name,mode).objectStore(name)},
 async get(name,id){return await new Promise((res,rej)=>{const r=this.store(name).get(id);r.onsuccess=()=>res(r.result||null);r.onerror=()=>rej(r.error);});},
 async queryBy(name,field,value){return new Promise((resolve,reject)=>{const rows=[],r=this.store(name).openCursor();r.onsuccess=()=>{const cursor=r.result;if(!cursor)return resolve(rows);if(cursor.value[field]===value)rows.push(cursor.value);cursor.continue()};r.onerror=()=>reject(r.error)})},
 async all(name){return await new Promise((res,rej)=>{const r=this.store(name).getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error);});},
 async put(name,obj){setSave('Saving…',false);obj.updatedAt=now();await new Promise((res,rej)=>{const r=this.store(name,'readwrite').put(obj);r.onsuccess=()=>res();r.onerror=()=>rej(r.error);});setSave('Saved locally',true);return obj;},
 async del(name,id){setSave('Saving…',false);await new Promise((res,rej)=>{const r=this.store(name,'readwrite').delete(id);r.onsuccess=()=>res();r.onerror=()=>rej(r.error);});setSave('Saved locally',true);},
 async clear(name){await new Promise((res,rej)=>{const r=this.store(name,'readwrite').clear();r.onsuccess=()=>res();r.onerror=()=>rej(r.error);});}
};

