function navActive(v){return State.view===v?'active':''}
function updateNetwork(){const e=document.getElementById('networkBadge');if(e){e.textContent=navigator.onLine?'Online':'Offline';e.style.color=navigator.onLine?'var(--good)':'var(--danger)'}document.querySelectorAll('.reader-ai-btn').forEach(b=>{b.disabled=!navigator.onLine;b.classList.toggle('offline',!navigator.onLine);b.title=navigator.onLine?'Ask AI about this source':'Ask AI requires an internet connection'})}
addEventListener('online',updateNetwork);addEventListener('offline',updateNetwork);

