function openSheet(title,body,actions=''){document.getElementById('sheetHost').innerHTML=`<div class="sheet-backdrop" onclick="if(event.target===this)closeSheet()"><div class="sheet"><div class="sheet-grab"></div><div class="sheet-head"><h2>${esc(title)}</h2><button class="btn icon ghost" onclick="closeSheet()">×</button></div>${body}${actions?`<div class="sheet-actions">${actions}</div>`:''}</div></div>`;}
