/* ----------------------------- Meta/recent ----------------------------- */
async function getMeta(id,def=null){const r=await Storage.get('meta',id);return r?r.value:def}
async function setMeta(id,value){await Storage.put('meta',{id,value,createdAt:now()})}
async function pushRecent(item){let r=await getMeta('recent',[]);r=[item,...r.filter(x=>!(x.type===item.type&&x.id===item.id))].slice(0,12);await setMeta('recent',r)}
async function setLastActive(v){await setMeta('lastActive',v)}

async function ensureRequestedCourseSubjects(){
 const existing=await Storage.all('subjects');
 const byCode=new Map(existing.filter(x=>x.courseCode).map(x=>[String(x.courseCode).trim().toUpperCase(),x]));
 const byName=new Map(existing.map(x=>[String(x.name||'').trim().toUpperCase(),x]));
 for(const course of REQUESTED_COURSE_SUBJECTS){
  const codeKey=course.courseCode.toUpperCase(),nameKey=course.name.toUpperCase();
  const match=byCode.get(codeKey)||byName.get(nameKey);
  if(match){
   let changed=false;
   if(match.courseCode!==course.courseCode){match.courseCode=course.courseCode;changed=true}
   if(match.name!==course.name){match.name=course.name;changed=true}
   if(changed)await Storage.put('subjects',match);
   continue;
  }
  const row={id:course.id,courseCode:course.courseCode,name:course.name,createdAt:now()};
  await Storage.put('subjects',row);
  byCode.set(codeKey,row);byName.set(nameKey,row);
 }
}


/* ----------------------------- Study Module registry / Android-safe launcher ----------------------------- */
function base64ToBlob(base64,type='text/html;charset=utf-8'){
 const bin=atob(base64),chunk=32768,parts=[];
 for(let i=0;i<bin.length;i+=chunk){const end=Math.min(bin.length,i+chunk),a=new Uint8Array(end-i);for(let j=i;j<end;j++)a[j-i]=bin.charCodeAt(j);parts.push(a)}
 return new Blob(parts,{type});
}
async function ensureBundledStudyModules(){
 for(const spec of BUNDLED_MODULES){
  let m=await Storage.get('modules',spec.moduleId);
  const needsBundle=!m?.blob||m.bundledVersion!==spec.version;
  const keepSummary=m?.summary||null,createdAt=m?.createdAt||now();
  m={...(m||{}),id:spec.moduleId,moduleId:spec.moduleId,subjectId:spec.subjectId,title:spec.title,subtitle:spec.subtitle,version:spec.version,schemaVersion:spec.schemaVersion,moduleType:spec.moduleType,capabilities:spec.capabilities,status:spec.status,fileName:spec.fileName,createdAt,summary:keepSummary,bundledVersion:spec.version};
  if(needsBundle)m.blob=base64ToBlob(spec.bundledBase64);
  await Storage.put('modules',m);
 }
}
function moduleSummaryLine(m){
 const x=m?.summary||{},bits=[];
 if(x.lastStudiedAt)bits.push('Last studied '+fmtDate(x.lastStudiedAt));
 if(Number.isFinite(x.coverage))bits.push('Coverage '+Math.round(x.coverage)+'%');
 if(Number.isFinite(x.mastery))bits.push('Mastery '+Math.round(x.mastery)+'%');
 if(Number.isFinite(x.reviewDue)&&x.reviewDue>0)bits.push('Review due '+x.reviewDue);
 return bits.join(' · ')||'Study Module';
}
function moduleRow(m){return `<div class="list-row"><button type="button" class="module-open-button" data-open-module="${esc(m.moduleId||m.id)}" aria-label="Study ${esc(m.title)}"><span class="list-main"><span class="list-title">${esc(m.title)}</span><span class="list-sub">${esc(m.subtitle||'Study Module')}</span>${m.summary?`<span class="muted small">${esc(moduleSummaryLine(m))}</span>`:''}</span></button><span class="state-pill">${esc(m.status||'READY')}</span><button class="kebab" aria-label="Module actions" onclick="openCombinedModuleMenu('${m.moduleId||m.id}')">⋯</button></div>`}

function modulePackageCheck(id,label,detail,checked=true,disabled=false){return `<label class="share-check"><input type="checkbox" id="${id}" ${checked?'checked':''} ${disabled?'disabled':''} onchange="refreshModulePackagePreview()"><span><b>${esc(label)}</b><span class="muted small" style="display:block">${esc(detail)}</span></span></label>`}
let ModulePackageDraft={moduleId:null};
async function openModulePackage(id){
 const m=await Storage.get('modules',id);if(!m)return toast('Study Module registration is missing');ModulePackageDraft={moduleId:id};
 const caps=new Set(m.capabilities||[]),isCh25=(m.moduleId||m.id)==='pharmacology-ch25-diabetes';
 const body=`<p class="muted">Choose exactly which parts of <b>${esc(m.title)}</b> you want to send. The result is one self-contained interactive HTML file that the recipient can open and use on their own device.</p>
 <div class="privacy-note"><b>Private by default:</b> your quiz answers, mastery/progress, weak-status history, and study history are not copied. Notes, annotations, and custom tables are included only if you explicitly turn them on below.</div>
 <div class="field"><label class="label">Package name</label><input class="input" id="modulePackageName" value="${esc(m.title+' — Shared Study Package')}"></div>
 <div class="section-title">Interactive sections</div>
 ${modulePackageCheck('mpReader','Reader','Original chapter/source reader. Recipient can use the Reader tools.',caps.has('reader'))}
 ${modulePackageCheck('mpGuide','Study Guide','Organized source-based study guide.',caps.has('studyGuide'))}
 ${modulePackageCheck('mpRecall','Active Recall','Hide/reveal and retrieval-practice tools.',caps.has('activeRecall'))}
 ${modulePackageCheck('mpTables','Reveal Tables','Interactive table study modes.',caps.has('tables'))}
 ${modulePackageCheck('mpCompare','Compare','Drug/topic comparison tools.',caps.has('compare')||isCh25)}
 ${modulePackageCheck('mpNotes','Notes Workspace','Lets the recipient create their own notes. Your current notes are not included unless selected below.',caps.has('notes'),false)}
 ${modulePackageCheck('mpQuiz','MCQ','Interactive A–D question bank with explanations.',caps.has('mcq'))}
 ${modulePackageCheck('mpWeak','Weak Topics','Recipient-side weak-topic review generated from their own activity.',caps.has('weakTopics'))}
 <div class="section-title" style="margin-top:14px">Optional personal layers</div>
 ${modulePackageCheck('mpMyNotes','Include my current module notes','Copies only the saved Chapter 25 Notes entries into the shared copy.',false,!isCh25)}
 ${modulePackageCheck('mpMyAnnotations','Include my Reader pen / marker annotations','Copies your existing Reader strokes. Leave off for a clean source copy.',false,!isCh25)}
 ${modulePackageCheck('mpMyTables','Include my custom tables','Copies custom tables you created inside this module.',false,!isCh25)}
 <div class="field"><label class="label">MCQ amount</label><select class="select" id="mpQuestionCount" onchange="refreshModulePackagePreview()"><option value="all">All available questions</option><option value="100">First 100</option><option value="50">First 50</option><option value="20">First 20</option></select></div>
 <div id="modulePackagePreview" class="card flat" style="margin-top:12px"></div>`;
 const actions=`<button class="btn" onclick="closeSheet()">Cancel</button><button class="btn" onclick="deliverModulePackage('${id}','download')">Download HTML</button><button class="btn primary" onclick="deliverModulePackage('${id}','share')">Share / Send Package</button>`;
 openSheet('Create Interactive Package',body,actions);setTimeout(refreshModulePackagePreview,0);
}
function readModulePackageConfig(){
 const g=id=>!!document.getElementById(id)?.checked;const tabs={reader:g('mpReader'),guide:g('mpGuide'),recall:g('mpRecall'),tables:g('mpTables'),compare:g('mpCompare'),hits:g('mpNotes'),quiz:g('mpQuiz'),weak:g('mpWeak')};
 if(tabs.weak&&!tabs.quiz){tabs.quiz=true;const q=document.getElementById('mpQuiz');if(q)q.checked=true}
 const n=document.getElementById('mpQuestionCount')?.value||'all';return {tabs,includeMyNotes:g('mpMyNotes')&&tabs.hits,includeMyAnnotations:g('mpMyAnnotations')&&tabs.reader,includeMyTables:g('mpMyTables')&&tabs.tables,questionCount:n};
}
function refreshModulePackagePreview(){const box=document.getElementById('modulePackagePreview');if(!box)return;const c=readModulePackageConfig(),labels={reader:'Reader',guide:'Study Guide',recall:'Active Recall',tables:'Reveal Tables',compare:'Compare',hits:'Notes',quiz:'MCQ',weak:'Weak Topics'},inc=Object.entries(c.tabs).filter(([,v])=>v).map(([k])=>labels[k]),personal=[];if(c.includeMyNotes)personal.push('your current notes');if(c.includeMyAnnotations)personal.push('your Reader annotations');if(c.includeMyTables)personal.push('your custom tables');box.innerHTML=`<div class="h3">Recipient will receive</div><div class="chips" style="margin-top:8px">${inc.length?inc.map(x=>`<span class="chip">${esc(x)}</span>`).join(''):'<span class="muted">No study section selected.</span>'}</div>${c.tabs.quiz?`<div class="muted small" style="margin-top:8px">MCQ selection: ${esc(c.questionCount==='all'?'all available questions':c.questionCount+' questions')}</div>`:''}<div class="muted small" style="margin-top:8px">Personal layers: ${personal.length?esc(personal.join(', ')):'none'}</div><div class="muted small" style="margin-top:8px">Recipient interactions save only in their copy. Your personal progress and quiz history are excluded.</div>`}
function moduleSenderState(m){try{if((m.moduleId||m.id)==='pharmacology-ch25-diabetes')return JSON.parse(localStorage.getItem('ch25_diabetes_study_v2')||'{}')||{}}catch(e){}return {}}
function packageSafeName(s){return String(s||'Study_Package').trim().replace(/[^a-z0-9._-]+/gi,'_').replace(/^_+|_+$/g,'').slice(0,110)||'Study_Package'}
function filterStudyModuleSource(source,cfg,m,seed,packageName,packageId){
 let html=source,allowed=Object.entries(cfg.tabs).filter(([,v])=>v).map(([k])=>k);if(!allowed.length)throw new Error('Choose at least one study section.');const first=allowed[0];
 // Prune the largest source-only data when the Reader is not shared; keep academic data only when an academic tool needs it.
 try{const mark='const DATA=',ds=html.indexOf(mark),de=html.indexOf('\n',ds);if(ds>=0&&de>ds){let raw=html.slice(ds+mark.length,de).trim();if(raw.endsWith(';'))raw=raw.slice(0,-1);const data=JSON.parse(raw),academic=cfg.tabs.guide||cfg.tabs.recall||cfg.tabs.tables||cfg.tabs.compare||cfg.tabs.quiz||cfg.tabs.weak;if(!cfg.tabs.reader){data.pageText=[];data.images=[]}if(!academic){data.classes=[];data.concepts=[];data.simple={};data.quiz=[];data.interactions={reduce:[],potentiate:[]}}else if(!cfg.tabs.quiz&&!cfg.tabs.weak)data.quiz=[];html=html.slice(0,ds)+mark+JSON.stringify(data)+';'+html.slice(de)}}catch(e){console.warn('Package data pruning skipped',e)}
 if(!cfg.tabs.quiz&&!cfg.tabs.weak)html=html.replace('DATA.quiz=buildWholeCoverageQuiz();','DATA.quiz=[];');else if(cfg.questionCount!=='all'){const n=Math.max(1,Math.min(180,+cfg.questionCount||180));html=html.replace('DATA.quiz=buildWholeCoverageQuiz();',`DATA.quiz=buildWholeCoverageQuiz().slice(0,${n});`)}
 const labels={reader:'Reader',guide:'Study Guide',recall:'Active Recall',tables:'Tables',compare:'Compare',hits:'Notes',quiz:'MCQ',weak:'Weak Topics'};const nav=allowed.map((k,i)=>`<button class="tab ${i===0?'active':''}" data-tab="${k}">${labels[k]}</button>`).join('');html=html.replace(/<nav class="tabs no-print">[\s\S]*?<\/nav>/,`<nav class="tabs no-print">${nav}</nav>`);
 const uniqueStore='psl_shared_'+packageId.replace(/[^a-z0-9_]/gi,'_');html=html.replace(/const STORE='[^']+';/,`const SHARE_PACKAGE_INFO=${JSON.stringify({packageId,title:packageName,allowed})};\nconst SHARED_SEED=${JSON.stringify(seed)};\nconst STORE='${uniqueStore}';`);html=html.replace('ensureState();',`try{if(!localStorage.getItem(STORE))state={...state,...SHARED_SEED,lastTab:${JSON.stringify(first)}}}catch(e){}\nensureState();`,1);
 const initMap={reader:'renderReader()',guide:'renderGuide()',recall:'renderRecall()',tables:'renderTables()',compare:'renderCompare()',hits:'renderHits()',quiz:'renderQuiz()',weak:'renderWeak()'},calls=allowed.map(k=>initMap[k]).filter(Boolean).join(';');html=html.replace("renderReader();renderGuide();renderRecall();renderTables();renderCompare();renderHits();renderQuiz();renderWeak();switchTab(state.lastTab||'reader');",`${calls};switchTab(${JSON.stringify(first)});`);
 const banner=`<div style="max-width:1180px;margin:10px auto 0;padding:0 14px"><div style="padding:9px 12px;border:1px solid #d9dee7;border-radius:10px;background:#fff;font:13px system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;color:#475467"><b>Shared interactive study package</b> · Your answers, notes, annotations, and progress in this copy stay on this device.</div></div>`;html=html.replace('<body>','<body>'+banner);html=html.replace(/<title>[\s\S]*?<\/title>/,`<title>${esc(packageName)}</title>`);return html;
}
async function createModulePackageFile(id){const m=await Storage.get('modules',id);if(!m)throw new Error('Study Module registration is missing');let blob=m.blob;if(!blob){const spec=BUNDLED_MODULES.find(x=>x.moduleId===(m.moduleId||m.id));if(spec)blob=base64ToBlob(spec.bundledBase64)}if(!blob)throw new Error('Study Module source is unavailable');const cfg=readModulePackageConfig(),source=await blob.text(),sender=(await getMeta('moduleState:'+(m.moduleId||m.id),null))||moduleSenderState(m),seed={lastTab:Object.entries(cfg.tabs).find(([,v])=>v)?.[0]||'reader'};if(cfg.includeMyNotes)seed.hits=Array.isArray(sender.hits)?sender.hits:[];if(cfg.includeMyAnnotations)seed.annotations=sender.annotations&&typeof sender.annotations==='object'?sender.annotations:{};if(cfg.includeMyTables)seed.customTables=Array.isArray(sender.customTables)?sender.customTables:[];const name=(document.getElementById('modulePackageName')?.value||m.title+' — Shared Study Package').trim(),pid=(m.moduleId||m.id)+'_'+Date.now().toString(36),html=prepareSharedModulePackage(filterStudyModuleSource(source,cfg,m,seed,name,pid),pid),fileName=packageSafeName(name)+'.html';return {file:new File([html],fileName,{type:'text/html'}),fileName,name,cfg}}
async function deliverModulePackage(id,mode){try{const out=await createModulePackageFile(id);if(mode==='share'&&navigator.share&&navigator.canShare?.({files:[out.file]})){try{await navigator.share({files:[out.file],title:out.name,text:'Interactive study package'});toast('Package ready to send');return}catch(e){if(e?.name==='AbortError')return;console.warn(e)}}const u=URL.createObjectURL(out.file),a=document.createElement('a');a.href=u;a.download=out.fileName;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000);toast(mode==='share'?'Sharing is unavailable here, so the HTML package was downloaded instead.':'Interactive package downloaded')}catch(e){console.error(e);toast(e.message||'Could not create package')}}

async function launchModule(id,resume=false){
 const m=await Storage.get('modules',id);
 if(!m)return toast('Study Module registration is missing');
 await pushRecent({type:'module',id:m.moduleId||m.id,at:now()});
 await setLastActive({moduleId:m.moduleId||m.id,subjectId:m.subjectId,at:now()});
 let blob=m.blob;
 if(!blob){
  const spec=BUNDLED_MODULES.find(x=>x.moduleId===m.moduleId);
  if(spec){blob=base64ToBlob(spec.bundledBase64);m.blob=blob;m.bundledVersion=spec.version;await Storage.put('modules',m)}
 }
 if(!blob)return toast('Study Module file is unavailable');
 let source=await prepareRefinedModuleSource(await blob.text(),id);
 let host=document.getElementById('moduleLaunchHost');
 if(!host){host=document.createElement('div');host.id='moduleLaunchHost';document.body.appendChild(host)}
 host.innerHTML=`<div class="module-launch-shell" role="dialog" aria-modal="true" aria-label="${esc(m.title)}"><div class="module-launch-head"><button class="btn small" onclick="closeModuleLaunch()">${ICONS.back} Library</button><div class="module-launch-title"><b>Study</b></div><button class="btn small ghost" onclick="closeModuleLaunch()" aria-label="Close Study Module">Close</button></div><div class="module-launch-loading" id="moduleLaunchLoading">Opening Study Module…</div><iframe id="moduleLaunchFrame" class="module-launch-frame" title="${esc(m.title)}"></iframe></div>`;
 document.body.classList.add('module-open');
 const frame=document.getElementById('moduleLaunchFrame');
 frame.name=resume&&m.summary?.resumeTarget?`psl-resume:${m.summary.resumeTarget}`:'';
 frame.addEventListener('load',()=>document.getElementById('moduleLaunchLoading')?.remove(),{once:true});
 frame.srcdoc=source;
}
function closeModuleLaunch(){
 const host=document.getElementById('moduleLaunchHost');if(host)host.innerHTML='';document.body.classList.remove('module-open');
 if(State.view==='subject')render();
}
window.addEventListener('message',async e=>{
 const msg=e.data;const activeFrame=document.getElementById('moduleLaunchFrame');if(!activeFrame||e.source!==activeFrame.contentWindow)return;if(!msg||msg.type!=='study-module-summary'||!msg.moduleId)return;
 const m=await Storage.get('modules',msg.moduleId);if(!m)return;
 if(msg.manifest&&msg.manifest.moduleId===m.moduleId){
  m.title=msg.manifest.title||m.title;m.subtitle=msg.manifest.subtitle||m.subtitle;m.version=msg.manifest.version||m.version;m.schemaVersion=msg.manifest.schemaVersion??m.schemaVersion;m.capabilities=Array.isArray(msg.manifest.capabilities)?msg.manifest.capabilities:m.capabilities;
 }
 if(msg.summary&&msg.summary.moduleId===m.moduleId)m.summary=msg.summary;
 m.updatedAt=now();await Storage.put('modules',m);
 if(State.view==='subject'&&State.subjectId===m.subjectId)render();
});


/* ----------------------------- Main render ----------------------------- */
async function render(){renderNav();updateNetwork();const calendarSide=document.getElementById('calendarSideLaunch');if(calendarSide)calendarSide.classList.toggle('active',State.view==='calendar');const main=document.getElementById('main');main.innerHTML='<div class="muted">Loading…</div>';try{
 if(State.view==='home')await renderHome(main);
 else if(State.view==='library')await renderLibrary(main);
 else if(State.view==='subject')await renderSubject(main);
 else if(State.view==='topic')await renderTopic(main);
 else if(State.view==='search')await renderSearch(main);
 else if(State.view==='calendar')await renderCalendar(main);
 else if(State.view==='settings')await renderSettings(main);
}catch(e){console.error(e);main.innerHTML=`<div class="card"><h2>Something went wrong</h2><p class="muted">${esc(e.message||e)}</p></div>`}}

/* ----------------------------- Home ----------------------------- */
async function renderHome(main){setTopTitle('My Study Library');const subjects=(await Storage.all('subjects')).sort(byUpdated);const recent=await getMeta('recent',[]);const last=await getMeta('lastActive',null);
 let cont='';if(last?.moduleId){const m=await Storage.get('modules',last.moduleId);if(m)cont=`<div class="card"><div class="section-head"><div><div class="h3">${esc(m.title)}</div><div class="muted small">Resume your last Study Module</div></div><button class="btn primary" onclick="launchModule('${m.moduleId||m.id}',true)">Continue</button></div></div>`}if(!cont&&last?.topicId){const t=await Storage.get('topics',last.topicId);if(t)cont=`<div class="card"><div class="section-head"><div><div class="h3">${esc(t.name)}</div><div class="muted small">Resume your last topic</div></div><button class="btn primary" onclick="openTopic('${t.id}')">Continue</button></div></div>`}if(!cont)cont='<div class="empty">Nothing yet.</div>';
 main.innerHTML=`<div class="view"><h1 class="h1">My Study Library</h1><p class="muted">Build your library as you study.</p>
 <div class="section"><div class="search"><input class="input" placeholder="Search your library…" onkeydown="if(event.key==='Enter'){Prefs.set('searchQuery',this.value);go('search')}"/><button class="btn" onclick="go('search')">${ICONS.search} Search</button></div></div>
 <div class="section"><div class="section-title">Continue Studying</div>${cont}</div>
 <div class="section"><div class="section-head"><div class="section-title">My Subjects</div>${subjects.length?'<button class="btn small" onclick="showCreateSubject()">+ Add subject</button>':''}</div>${subjects.length?`<div class="grid grid2">${subjects.slice(0,6).map(subjectCard).join('')}</div>`:`<div class="empty">No subjects yet.<br><br><button class="btn primary" onclick="showCreateSubject()">+ Add Subject</button></div>`}</div>
 <div class="section"><div class="section-title">Recent</div>${recent.length?`<div class="list">${(await Promise.all(recent.slice(0,6).map(recentRow))).filter(Boolean).join('')}</div>`:'<div class="empty">Nothing yet.</div>'}</div></div>`;}
function subjectCard(s){const code=(s.courseCode||'').trim();return `<div class="card subject-card">${code?`<div class="subject-code">${esc(code)}</div>`:`<div class="subject-icon">${esc((s.icon||s.name.slice(0,1)||'S').slice(0,2).toUpperCase())}</div>`}<div class="list-main"><div class="list-title">${esc(s.name)}</div><div class="list-sub">Open subject</div></div><button class="btn small" onclick="openSubject('${s.id}')">Open</button></div>`}
async function recentRow(r){if(r.type==='module'){const m=await Storage.get('modules',r.id);if(!m)return '';return `<div class="list-row"><div class="list-main"><div class="list-title">${esc(m.title)}</div><div class="list-sub">Study Module · ${fmtDate(r.at)}</div></div><button class="btn small" onclick="launchModule('${m.moduleId||m.id}',true)">Open</button></div>`}if(r.type==='topic'){const t=await Storage.get('topics',r.id);if(!t)return '';return `<div class="list-row"><div class="list-main"><div class="list-title">${esc(t.name)}</div><div class="list-sub">Topic · ${fmtDate(r.at)}</div></div><button class="btn small" onclick="openTopic('${t.id}')">Open</button></div>`}if(r.type==='material'){const m=await Storage.get('materials',r.id);if(!m)return '';return `<div class="list-row"><div class="list-main"><div class="list-title">${esc(m.name)}</div><div class="list-sub">Material · ${fmtDate(r.at)}</div></div><button class="btn small" onclick="openMaterialFromRecent('${m.id}')">Open</button></div>`}return ''}

/* ----------------------------- Library ----------------------------- */
async function renderLibrary(main){setTopTitle('Library');const subjects=(await Storage.all('subjects')).sort(byUpdated);main.innerHTML=`<div class="view"><div class="section-head"><div><h1 class="h1">Library</h1><p class="muted">Subjects, chapters, and topics.</p></div><button class="btn primary" onclick="showCreateSubject()">+ Add Subject</button></div>${subjects.length?`<div class="grid grid2">${subjects.map(subjectCard).join('')}</div>`:`<div class="empty">No subjects yet.<br><br><button class="btn primary" onclick="showCreateSubject()">+ Add Subject</button></div>`}</div>`}
async function openSubject(id){State.subjectId=id;State.topicId=null;await pushRecent({type:'subject',id,at:now()});go('subject',{subjectId:id})}

/* ----------------------------- Subject creation + page ----------------------------- */
function showCreateSubject(){openSheet('Create Subject',`<form id="subjectForm"><div class="field"><label class="label">Subject Name</label><input class="input" id="subjectName" required autofocus></div><div class="grid grid2"><div class="field"><label class="label">Color (optional)</label><input class="input" id="subjectColor" type="color" value="#3457d5"></div><div class="field"><label class="label">Icon (optional)</label><input class="input" id="subjectIcon" maxlength="2" placeholder="e.g. PH"></div></div></form>`,`<button class="btn" onclick="closeSheet()">Cancel</button><button class="btn primary" onclick="createSubject()">Create Subject</button>`)}
async function createSubject(){const name=document.getElementById('subjectName').value.trim();if(!name)return toast('Enter a subject name');const s={id:uid('sub'),name,color:document.getElementById('subjectColor').value,icon:document.getElementById('subjectIcon').value.trim(),createdAt:now()};await Storage.put('subjects',s);closeSheet();await openSubject(s.id)}
async function renderSubject(main){const s=await Storage.get('subjects',State.subjectId);if(!s)return go('library');setTopTitle(s.name);const modules=(await Storage.all('modules')).filter(x=>x.subjectId===s.id).sort(byUpdated);const chapters=(await Storage.all('chapters')).filter(x=>x.subjectId===s.id).sort(byUpdated);const topics=(await Storage.all('topics')).filter(x=>x.subjectId===s.id).sort(byUpdated);const direct=topics.filter(t=>!t.chapterId);
 main.innerHTML=`<div class="view"><button class="btn small ghost" onclick="go('library')">${ICONS.back} Library</button><div class="section-head"><div>${s.courseCode?`<div class="muted small" style="font-weight:800;letter-spacing:.04em;margin-bottom:4px">${esc(s.courseCode)}</div>`:''}<h1 class="h1">${esc(s.name)}</h1><p class="muted">${modules.length+chapters.length+direct.length?'Subject workspace · open Study Modules or organize chapters and topics here.':'No Study Modules, chapters, or topics yet.'}</p></div><button class="kebab" onclick="openEntityMenu('subjects','${s.id}')">⋯</button></div>
 <div class="chips"><button class="btn small" onclick="showCreateChapter('${s.id}')">+ Add Chapter</button><button class="btn small primary" onclick="showCreateTopic('${s.id}')">+ Add Topic</button></div>
 <div class="section"><div class="section-title">Study Modules</div>${modules.length?`<div class="list">${modules.map(moduleRow).join('')}</div>`:'<div class="empty">No Study Modules registered yet.</div>'}</div>
 <div class="section"><div class="section-title">Chapters / Units</div>${chapters.length?`<div class="list">${chapters.map(c=>chapterBlock(c,topics.filter(t=>t.chapterId===c.id))).join('')}</div>`:'<div class="empty">No chapters yet. Chapters are optional.</div>'}</div>
 <div class="section"><div class="section-title">Topics directly under subject</div>${direct.length?`<div class="list">${direct.map(topicRow).join('')}</div>`:'<div class="empty">No direct topics yet.</div>'}</div></div>`;}
function chapterBlock(c,topics){return `<div class="card flat"><div class="section-head"><div><div class="h3">${esc(c.name)}</div><div class="muted small">${topics.length} topic${topics.length===1?'':'s'}</div></div><button class="kebab" onclick="openEntityMenu('chapters','${c.id}')">⋯</button></div>${topics.length?`<div class="list">${topics.map(topicRow).join('')}</div>`:`<div class="empty">No topics yet.<br><br><button class="btn small" onclick="showCreateTopic('${c.subjectId}','${c.id}')">+ Add Topic</button></div>`}</div>`}
function topicRow(t){return `<div class="list-row"><div class="list-main"><div class="list-title">${esc(t.name)}</div><div class="list-sub">Topic</div></div><button class="btn small" onclick="openTopic('${t.id}')">Open</button><button class="kebab" onclick="event.stopPropagation();openEntityMenu('topics','${t.id}')">⋯</button></div>`}
function showCreateChapter(subjectId){openSheet('Add Chapter / Unit',`<div class="field"><label class="label">Chapter / Unit Name</label><input class="input" id="chapterName" autofocus></div>`,`<button class="btn" onclick="closeSheet()">Cancel</button><button class="btn primary" onclick="createChapter('${subjectId}')">Create</button>`)}
async function createChapter(subjectId){const name=document.getElementById('chapterName').value.trim();if(!name)return toast('Enter a chapter name');await Storage.put('chapters',{id:uid('chap'),subjectId,name,createdAt:now()});closeSheet();render()}
async function showCreateTopic(subjectId,chapterId=''){const chapters=(await Storage.all('chapters')).filter(x=>x.subjectId===subjectId);openSheet('Add Topic',`<div class="field"><label class="label">Topic Name</label><input class="input" id="topicName" autofocus></div><div class="field"><label class="label">Location</label><select class="select" id="topicChapter"><option value="">Directly under subject</option>${chapters.map(c=>`<option value="${c.id}" ${c.id===chapterId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>`,`<button class="btn" onclick="closeSheet()">Cancel</button><button class="btn primary" onclick="createTopic('${subjectId}')">Create Topic</button>`)}
async function createTopic(subjectId){const name=document.getElementById('topicName').value.trim();if(!name)return toast('Enter a topic name');const t={id:uid('topic'),subjectId,chapterId:document.getElementById('topicChapter').value||null,name,createdAt:now()};await Storage.put('topics',t);closeSheet();await openTopic(t.id)}

/* ----------------------------- Entity menu / trash ----------------------------- */
async function openEntityMenu(store,id){const item=await Storage.get(store,id);if(!item)return;openSheet(item.name||'Options',`<button class="sheet-option" onclick="renameEntity('${store}','${id}')">Rename</button>${store==='topics'?`<button class="sheet-option" onclick="moveTopic('${id}')">Move</button><button class="sheet-option" onclick="duplicateTopic('${id}')">Duplicate</button>`:''}<button class="sheet-option danger" onclick="deleteEntity('${store}','${id}')">Move to Recently Deleted</button>`)}
async function renameEntity(store,id){const item=await Storage.get(store,id);openSheet('Rename',`<input class="input" id="renameValue" value="${esc(item.name||'')}">`,`<button class="btn" onclick="closeSheet()">Cancel</button><button class="btn primary" onclick="doRename('${store}','${id}')">Save</button>`)}
async function doRename(store,id){const item=await Storage.get(store,id);item.name=document.getElementById('renameValue').value.trim()||item.name;await Storage.put(store,item);closeSheet();render()}
async function moveTopic(id){const t=await Storage.get('topics',id), chapters=(await Storage.all('chapters')).filter(c=>c.subjectId===t.subjectId);openSheet('Move Topic',`<select class="select" id="moveChapter"><option value="">Directly under subject</option>${chapters.map(c=>`<option value="${c.id}" ${c.id===t.chapterId?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`,`<button class="btn" onclick="closeSheet()">Cancel</button><button class="btn primary" onclick="doMoveTopic('${id}')">Move</button>`)}
async function doMoveTopic(id){const t=await Storage.get('topics',id);t.chapterId=document.getElementById('moveChapter').value||null;await Storage.put('topics',t);closeSheet();render()}
async function duplicateTopic(id){const t=await Storage.get('topics',id);const copy={...t,id:uid('topic'),name:t.name+' Copy',createdAt:now(),updatedAt:now()};await Storage.put('topics',copy);closeSheet();toast('Topic duplicated');render()}
async function deleteEntity(store,id){const item=await Storage.get(store,id);closeSheet();confirmSheet('Move to Recently Deleted',`Move “${item.name||'this item'}” to Recently Deleted?`,async()=>{await Storage.put('trash',{id:uid('trash'),originalStore:store,originalId:id,payload:item,deletedAt:now(),createdAt:now()});await Storage.del(store,id);if(store==='subjects')go('library');else if(store==='topics')go('subject');else render()})}

/* ----------------------------- Topic workspace ----------------------------- */
async function openTopic(id){const t=await Storage.get('topics',id);if(!t)return;State.topicId=id;State.subjectId=t.subjectId;State.topicTool='overview';State.materialId=null;await pushRecent({type:'topic',id,at:now()});await setLastActive({topicId:id,at:now()});go('topic',{topicId:id,subjectId:t.subjectId})}
async function computeTopicProgress(topicId){const records=(await Storage.queryBy('progress','topicId',topicId));const rows=records.filter(p=>p.kind==='question'||p.kind==='flashcard');if(!rows.some(p=>p.studyRecord?.attempts||Array.isArray(p.attempts)&&p.attempts.length))return null;const [qs,cs]=await Promise.all([Storage.queryBy('questions','topicId',topicId),Storage.queryBy('flashcards','topicId',topicId)]);const total=qs.length+cs.length;if(!total)return null;return Math.round(rows.filter(p=>p.studyRecord?.mastered).length/total*100)}
async function renderTopic(main){const t=await Storage.get('topics',State.topicId);if(!t)return go('library');const s=await Storage.get('subjects',t.subjectId);const prog=await computeTopicProgress(t.id);setTopTitle(t.name);main.innerHTML=`<div class="view"><button class="btn small ghost" onclick="openSubject('${t.subjectId}')">${ICONS.back} ${esc(s?.name||'Subject')}</button><div class="card topic-hero"><div class="grow"><h1 class="h1">${esc(t.name)}</h1><div class="muted">${prog===null?'Not enough activity yet.':`Progress: ${prog}%`}</div>${prog!==null?`<div class="progressbar" style="margin-top:9px"><div style="width:${prog}%"></div></div>`:''}</div><button class="kebab" onclick="openEntityMenu('topics','${t.id}')">⋯</button></div>
 <div class="section"><div class="tool-tabs">${[['overview','Overview'],['reader','Reader'],['notes','Notes'],['flashcards','Flashcards'],['quiz','Quiz'],['tables','Tables'],['progress','Progress'],['share','Share Topic']].map(([k,l])=>`<button class="tool-tab ${State.topicTool===k?'active':''}" onclick="setTopicTool('${k}')">${l}</button>`).join('')}</div><div id="topicTool"></div></div></div>`;await renderTopicTool();}
function setTopicTool(k){State.topicTool=k;State.materialId=null;renderTopicTool()}
async function renderTopicTool(){const host=document.getElementById('topicTool');if(!host)return;if(State.topicTool==='overview')await topicOverview(host);else if(State.topicTool==='reader')await topicReader(host);else if(State.topicTool==='notes')await topicNotes(host);else if(State.topicTool==='flashcards')await topicFlashcards(host);else if(State.topicTool==='quiz')await topicQuiz(host);else if(State.topicTool==='tables')await topicTables(host);else if(State.topicTool==='progress')await topicProgress(host);else if(State.topicTool==='share')await topicShare(host)}
async function topicOverview(host){const id=State.topicId;const mats=(await Storage.all('materials')).filter(x=>x.topicId===id);const notes=(await Storage.all('notes')).filter(x=>x.topicId===id);const fs=(await Storage.all('flashcardSets')).filter(x=>x.topicId===id);const qs=(await Storage.all('quizSets')).filter(x=>x.topicId===id);const tabs=(await Storage.all('tables')).filter(x=>x.topicId===id);const any=mats.length+notes.length+fs.length+qs.length+tabs.length;host.innerHTML=`${!any?`<div class="empty"><h3>Nothing added yet.</h3><p>Add the first study material when you’re ready.</p><button class="btn primary" onclick="openAddMaterial()">+ Add Study Material</button></div>`:`<div class="card"><div class="section-head"><div><div class="h2">Study Materials & Tools</div><div class="muted">Everything here belongs only to this topic.</div></div><button class="btn primary" onclick="openAddMaterial()">+ Add Study Material</button></div><div class="metric-grid"><div class="metric"><span class="muted small">Reader / files</span><b>${mats.length}</b></div><div class="metric"><span class="muted small">Notes</span><b>${notes.length}</b></div><div class="metric"><span class="muted small">Flashcard sets</span><b>${fs.length}</b></div><div class="metric"><span class="muted small">Quiz sets</span><b>${qs.length}</b></div></div><div class="chips" style="margin-top:10px"><button class="btn small" onclick="setTopicTool('reader')">Reader</button><button class="btn small" onclick="setTopicTool('notes')">Notes</button><button class="btn small" onclick="setTopicTool('flashcards')">Flashcards</button><button class="btn small" onclick="setTopicTool('quiz')">Quiz</button><button class="btn small" onclick="setTopicTool('tables')">Tables (${tabs.length})</button></div></div>`}`}

/* ----------------------------- Universal add / topic material add ----------------------------- */
async function openUniversalAdd(){if(State.view==='topic'&&State.topicId)return openAddMaterial();if(State.view==='subject'&&State.subjectId){openSheet('Add',`<button class="sheet-option" onclick="closeSheet();showCreateChapter('${State.subjectId}')">Add Chapter / Unit</button><button class="sheet-option" onclick="closeSheet();showCreateTopic('${State.subjectId}')">Add Topic</button><button class="sheet-option" onclick="closeSheet();showCreateSubject()">Add Subject</button>`);return}openSheet('Add',`<button class="sheet-option" onclick="closeSheet();showCreateSubject()">Add Subject<span>Create the next subject in your library.</span></button>`)}
function openAddMaterial(){openSheet('Add Study Material',`<div class="privacy-note" style="margin-bottom:10px"><b>Current build:</b> items added here are stored inside this topic. <b>Future roadmap:</b> source uploads will offer <b>Store as File</b> or <b>Create Study Module</b>. Study Module creation is intentionally not active yet, and the original source will remain preserved when that workflow is implemented.</div><button class="sheet-option" onclick="chooseFile('pdf')">Upload PDF<span>Store the original source locally for offline access.</span></button><button class="sheet-option" onclick="chooseFile('document')">Upload Document<span>Store the source now; a future Study Module can be built around it.</span></button><button class="sheet-option" onclick="chooseFile('powerpoint')">Upload PowerPoint<span>Store the source now; a future Study Module can be built around it.</span></button><button class="sheet-option" onclick="showPasteText()">Paste Notes / Text<span>Creates a selectable text reader while preserving the pasted source.</span></button><button class="sheet-option" onclick="closeSheet();setTopicTool('notes');setTimeout(()=>showNewNote(),50)">Create Note</button><button class="sheet-option" onclick="closeSheet();setTopicTool('flashcards');setTimeout(()=>showCreateFlashSet(),50)">Create Flashcards</button><button class="sheet-option" onclick="closeSheet();setTopicTool('quiz');setTimeout(()=>showCreateQuizSet(),50)">Create MCQ Set</button><button class="sheet-option" onclick="closeSheet();setTopicTool('tables');setTimeout(()=>showCreateTable(),50)">Create Study Table</button><div class="privacy-note" style="margin-top:10px"><b>Planned Study Module:</b> Source File → Reader → Study Guide / Active Recall / Reveal Tables / Notes / MCQs / Progress / Weak Topics. The exact tools can adapt to the subject and source. AI remains optional and future-generated content should start as a reviewable draft.</div>`)}
function chooseFile(kind){const i=document.createElement('input');i.type='file';i.accept=kind==='pdf'?'.pdf,application/pdf':kind==='document'?'.txt,.md,.doc,.docx,.rtf,.odt':'.ppt,.pptx';i.onchange=async()=>{if(!i.files[0])return;await addFileMaterial(i.files[0],kind);closeSheet();State.topicTool='reader';await renderTopicTool()};i.click()}
async function addFileMaterial(file,kind){const id=uid('mat');await Storage.put('materials',{id,topicId:State.topicId,name:file.name,type:kind==='pdf'?'pdf':'file',mime:file.type||'',blob:file,size:file.size,state:'LOCAL ONLY',openCount:0,createdAt:now()});toast('Material added locally')}
function showPasteText(){openSheet('Paste Notes / Text',`<div class="field"><label class="label">Material title</label><input class="input" id="textTitle"></div><div class="field"><label class="label">Content</label><textarea class="textarea" id="textBody" rows="12"></textarea></div>`,`<button class="btn" onclick="closeSheet()">Cancel</button><button class="btn primary" onclick="savePastedText()">Add to Reader</button>`)}
async function savePastedText(){const title=document.getElementById('textTitle').value.trim()||'Untitled text';const content=document.getElementById('textBody').value;if(!content.trim())return toast('Paste some text first');await Storage.put('materials',{id:uid('mat'),topicId:State.topicId,name:title,type:'text',content,state:'LOCAL ONLY',openCount:0,createdAt:now()});closeSheet();State.topicTool='reader';await renderTopicTool()}

/* ----------------------------- Reader engine ----------------------------- */
const ReaderPrefs={
 get(){const stylus=!!Prefs.get('readerStylusDetected',false);return {penColor:Prefs.get('penColor','#111827'),penSize:+Prefs.get('penSize',3),hlColor:Prefs.get('hlColor','#ffe66d'),hlSize:+Prefs.get('hlSize',18),hlOpacity:+Prefs.get('hlOpacity',0.34),straight:!!Prefs.get('hlStraight',false),drawWithFinger:Prefs.get('readerDrawWithFinger',!stylus),pressure:Prefs.get('readerPressure',true)!==false,stylusDetected:stylus,lastPointerType:Prefs.get('readerLastPointerType','')};}
};
async function topicReader(host){const mats=(await Storage.all('materials')).filter(x=>x.topicId===State.topicId).sort(byUpdated);if(!mats.length){host.innerHTML=`<div class="empty">No reading materials yet.<br><br><button class="btn primary" onclick="openAddMaterial()">+ Add Study Material</button></div>`;return}if(!State.materialId){host.innerHTML=`<div class="section-head"><div><div class="h2">Reader</div><div class="muted">Open a source to read and annotate.</div></div><button class="btn" onclick="openAddMaterial()">+ Add Study Material</button></div><div class="material-grid">${mats.map(materialCard).join('')}</div>`;return}await renderReaderMaterial(host,State.materialId)}
function materialCard(m){return `<div class="material-card"><button type="button" class="material-open" data-open-material="${esc(m.id)}" aria-label="Read ${esc(m.name)}"><span class="material-icon">${m.type==='pdf'?'PDF':m.type==='text'?'TXT':'FILE'}</span><span class="list-main"><span class="list-title">${esc(m.name)}</span><span class="list-sub">${m.type==='text'?'Selectable text reader':m.type==='pdf'?'In-app PDF reader':'Stored file'}</span></span></button><span class="state-pill">${esc(m.state||'LOCAL ONLY')}</span><button type="button" class="kebab" data-material-menu="${esc(m.id)}" aria-label="File options for ${esc(m.name)}">⋯</button></div>`}
async function openMaterial(id){State.materialId=id;const m=await Storage.get('materials',id);if(!m)return toast('This file is unavailable. Restore it from your backup.');m.openCount=(m.openCount||0)+1;await Storage.put('materials',m);await pushRecent({type:'material',id,at:now()});await setLastActive({topicId:m.topicId,materialId:id,at:now()});renderTopicTool()}
async function openMaterialFromRecent(id){const m=await Storage.get('materials',id);if(!m)return;State.topicId=m.topicId;const t=await Storage.get('topics',m.topicId);State.subjectId=t.subjectId;State.topicTool='reader';State.materialId=id;go('topic',{topicId:m.topicId,subjectId:t.subjectId,topicTool:'reader',materialId:id})}
function readerToolBtn(tool,label,icon){return `<button class="reader-tool ${State.readerTool===tool?'active':''}" aria-label="${label}" title="${label}" onclick="setReaderTool('${tool}')">${icon}</button>`}
async function renderReaderMaterial(host,id){const m=await Storage.get('materials',id);if(!m){State.materialId=null;return topicReader(host)}State.readerMaterialType=m.type;const textHighlighter=m.type==='text'?readerToolBtn('textHighlight','Text Highlighter',ICONS.marker):'';host.innerHTML=`<div class="reader-shell"><div class="section-head"><div><button class="btn small ghost" onclick="closeActiveReader();State.materialId=null;renderTopicTool()">${ICONS.back} Materials</button><div class="h2" style="margin-top:8px">${esc(m.name)}</div><div class="muted small">${esc(m.state||'LOCAL ONLY')}</div></div><button class="kebab" onclick="openMaterialMenu('${m.id}')">⋯</button></div>
 <div class="reader-toolbar">${readerToolBtn('select','Browse / Select',ICONS.select)}${readerToolBtn('pen','Pen',ICONS.pen)}${textHighlighter}${readerToolBtn('freeHighlight','Marker',ICONS.marker)}${readerToolBtn('eraser','Eraser',ICONS.eraser)}<button class="reader-tool" aria-label="Undo" title="Undo" onclick="undoAnnotation()">${ICONS.undo}</button><button class="reader-tool" aria-label="Redo" title="Redo" onclick="redoAnnotation()">${ICONS.redo}</button><button class="reader-tool" aria-label="Bookmark" title="Bookmark" onclick="bookmarkReader()">${ICONS.bookmark}</button><button class="reader-tool" aria-label="Note" title="Note" onclick="noteFromReader()">${ICONS.note}</button><button class="reader-tool reader-ai-btn ${navigator.onLine?'':'offline'}" aria-label="Ask AI" title="${navigator.onLine?'Ask AI about this source':'Ask AI requires an internet connection'}" onclick="openReaderAIHelp()" ${navigator.onLine?'':'disabled'}><span>AI</span><span class="reader-ai-dot" aria-hidden="true"></span></button></div>
 <div id="readerSettings"></div><div id="readerContent"></div></div>`;renderReaderSettings();await mountReaderContent(m)}
function setReaderTool(t){State.readerTool=t;State.lastSelection=null;renderReaderSettings();configureReaderInput()}
function setReaderPref(k,v){Prefs.set(k,v);renderReaderSettings();configureReaderInput()}
function renderReaderSettings(){const h=document.getElementById('readerSettings');if(!h)return;const p=ReaderPrefs.get(),pdf=State.readerMaterialType==='pdf';const inputControls=pdf&&['pen','freeHighlight','eraser'].includes(State.readerTool)?`<label class="checkline small"><input type="checkbox" ${p.drawWithFinger?'checked':''} onchange="setReaderPref('readerDrawWithFinger',this.checked)"> Draw with finger</label>${State.readerTool==='pen'?`<label class="checkline small"><input type="checkbox" ${p.pressure?'checked':''} onchange="setReaderPref('readerPressure',this.checked)"> Pressure sensitivity</label>`:''}${p.stylusDetected?'<span class="pdf-stylus-status"><span class="pdf-stylus-dot"></span>Stylus active</span>':''}`:'';if(State.readerTool==='pen'){h.innerHTML=`<div class="tool-settings"><span class="small muted">Pen</span>${['#111827','#ffffff','#dc2626','#2563eb','#16a34a','#7c3aed'].map(c=>`<button aria-label="Pen color" class="color-dot ${p.penColor===c?'selected':''}" style="background:${c}" onclick="Prefs.set('penColor','${c}');renderReaderSettings()"></button>`).join('')}<input aria-label="Pen thickness" class="mini-range" type="range" min="1" max="10" step=".5" value="${p.penSize}" oninput="Prefs.set('penSize',this.value);renderReaderSettings()"><div class="preview-line"><span style="height:${p.penSize}px;background:${p.penColor}"></span></div>${inputControls}</div>`}else if(State.readerTool==='freeHighlight'||State.readerTool==='textHighlight'){h.innerHTML=`<div class="tool-settings"><span class="small muted">${State.readerTool==='freeHighlight'?'Marker':'Highlighter'}</span>${[['#ffe66d','Yellow'],['#ffb3c7','Pink'],['#a7d8ff','Blue'],['#bdecc8','Green'],['#d4b9ff','Purple'],['#ffc98b','Orange']].map(([c,n])=>`<button aria-label="${n}" title="${n}" class="color-dot ${p.hlColor===c?'selected':''}" style="background:${c}" onclick="Prefs.set('hlColor','${c}');renderReaderSettings()"></button>`).join('')}<label class="small muted">Size</label><input aria-label="Marker thickness" class="mini-range" type="range" min="8" max="42" value="${p.hlSize}" oninput="Prefs.set('hlSize',this.value);renderReaderSettings()"><label class="small muted">Opacity</label><input aria-label="Marker opacity" class="mini-range" type="range" min=".15" max=".55" step=".05" value="${p.hlOpacity}" oninput="Prefs.set('hlOpacity',this.value);renderReaderSettings()">${State.readerTool==='freeHighlight'?`<label class="checkline small"><input type="checkbox" ${p.straight?'checked':''} onchange="Prefs.set('hlStraight',this.checked)"> Straight assist</label>`:''}<div class="preview-line"><span style="height:${Math.min(18,p.hlSize)}px;background:${p.hlColor};opacity:${p.hlOpacity}"></span></div>${State.readerTool==='textHighlight'?'<button class="btn small primary" onclick="applyTextHighlight()">Apply to selected text</button>':''}${inputControls}</div>`}else if(State.readerTool==='eraser'&&pdf){h.innerHTML=`<div class="tool-settings"><span class="small muted">Eraser</span>${inputControls}</div>`}else h.innerHTML=''}


/* ----------------------------- Online Reader AI helper ----------------------------- */
const ReaderAI={context:'',materialName:'',page:null,sourceKind:'',question:''};
function readerAITruncate(text,max=5200){const t=String(text||'').replace(/\s+/g,' ').trim();return t.length>max?t.slice(0,max)+'…':t}
async function getReaderAIContext(){
 const m=State.materialId?await Storage.get('materials',State.materialId):null;if(!m)return {context:'',materialName:'Study material',page:null,sourceKind:'source'};
 let selected='';try{selected=String(window.getSelection?.()?.toString?.()||'').trim()}catch{}
 if(!selected&&State.lastSelection?.text)selected=String(State.lastSelection.text||'').trim();
 if(selected)return {context:readerAITruncate(selected),materialName:m.name||'Study material',page:m.type==='pdf'&&PdfReader.active()?PdfReader.pageNumber:null,sourceKind:'selected text'};
 if(m.type==='pdf'&&PdfReader.active()){
  let text='';try{text=await pdfPageText(PdfReader.pageNumber)}catch{}
  return {context:readerAITruncate(text),materialName:m.name||'PDF',page:PdfReader.pageNumber,sourceKind:'current PDF page'};
 }
 if(m.type==='text')return {context:readerAITruncate(m.content||''),materialName:m.name||'Text material',page:null,sourceKind:'current text material'};
 return {context:'',materialName:m.name||'Study material',page:null,sourceKind:'source'};
}
async function openReaderAIHelp(){
 if(!navigator.onLine)return toast('Ask AI is available only while online');
 const ctx=await getReaderAIContext();Object.assign(ReaderAI,ctx);ReaderAI.question='Explain this in simple terms without removing important details.';
 const pageLabel=ctx.page?` · page ${ctx.page}`:'';
 const preview=ctx.context||'No extractable text was found on this source. You can still type a question.';
 openSheet('Ask AI',`<div class="muted small">${esc(ctx.materialName)}${pageLabel}</div><div class="reader-ai-quick"><button class="btn small" onclick="readerAISetQuestion('Explain this in simple terms without removing important details.')">Explain simply</button><button class="btn small" onclick="readerAISetQuestion('Explain this step by step and connect the ideas.')">Step by step</button><button class="btn small" onclick="readerAISetQuestion('Give me a concrete example that makes this easier to understand.')">Give example</button><button class="btn small" onclick="readerAISetQuestion('What is the exam-relevant point here and what could confuse me?')">Exam point</button><button class="btn small" onclick="readerAISetQuestion('Turn this into 3 quick active-recall questions, then give the answers separately.')">Recall me</button></div><div class="field"><label class="label">What do you want explained?</label><textarea class="textarea" id="readerAIQuestion">${esc(ReaderAI.question)}</textarea></div><div class="field"><label class="label">Context that will be sent</label><div class="reader-ai-context">${esc(preview)}</div></div><div class="reader-ai-privacy">Nothing is sent automatically. This static offline-first app does not store an AI secret key. When you choose Send, only this question and the shown source context are prepared for the AI app.</div>`,`<button class="btn" onclick="readerAICopyPrompt()">Copy Prompt</button><button class="btn" onclick="readerAISharePrompt()">Send to AI App</button><button class="btn primary" onclick="readerAIOpenChatGPT()">Copy + Open ChatGPT</button>`);
}
function readerAISetQuestion(q){const e=document.getElementById('readerAIQuestion');if(e){e.value=q;e.focus()}}
function readerAIBuildPrompt(){
 const q=(document.getElementById('readerAIQuestion')?.value||ReaderAI.question||'Explain this.').trim();
 const where=ReaderAI.page?`${ReaderAI.materialName}, page ${ReaderAI.page}`:ReaderAI.materialName;
 return `You are helping me study from my own academic source. Use the excerpt below as the PRIMARY basis. Preserve the source terminology and do not silently replace it with outside knowledge. If the excerpt does not support a point, say so. If outside knowledge would help, clearly label it as \"Outside explanation\".\n\nMy question:\n${q}\n\nSource: ${where}\nContext type: ${ReaderAI.sourceKind}\n\nSource excerpt:\n${ReaderAI.context||'[No extractable source text was available. Answer only the question and state that source context was unavailable.]'}\n\nAnswer clearly. Start with the direct explanation, then the key idea to remember, then one short self-check question.`
}
async function copyTextSafe(text){try{await navigator.clipboard.writeText(text);return true}catch{}try{const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();const ok=document.execCommand('copy');ta.remove();return ok}catch{return false}}
async function readerAICopyPrompt(showToast=true){const ok=await copyTextSafe(readerAIBuildPrompt());if(showToast)toast(ok?'AI prompt copied':'Could not copy automatically');return ok}
async function readerAISharePrompt(){
 if(!navigator.onLine)return toast('Internet connection required');const prompt=readerAIBuildPrompt();
 if(navigator.share){try{await navigator.share({title:'Ask AI about my study material',text:prompt});return}catch(e){if(e?.name==='AbortError')return}}
 await readerAICopyPrompt(false);toast('Prompt copied. Choose your AI app and paste it.');
}
async function readerAIOpenChatGPT(){
 if(!navigator.onLine)return toast('Internet connection required');const ok=await readerAICopyPrompt(false);const w=window.open('https://chatgpt.com/','_blank','noopener');if(!w)toast(ok?'Prompt copied — open ChatGPT and paste it':'Allow pop-ups, then try again');else toast(ok?'Prompt copied — paste it into ChatGPT':'ChatGPT opened; copy the prompt manually if needed');
}

let activeObjectURL=null;
function closeActiveReader(){PdfReader.reset();if(activeObjectURL){URL.revokeObjectURL(activeObjectURL);activeObjectURL=null}canvasEl=null;canvasCtx=null;drawing=false;currentStroke=null}
async function mountReaderContent(m){const host=document.getElementById('readerContent');if(!host)return;closeActiveReader();if(m.type==='text'){const anns=(await Storage.all('annotations')).filter(a=>a.materialId===m.id);host.innerHTML=`<div class="reader-wrap"><div class="reader-scroll" id="readerScroll"><div class="reader-text" id="readerText"></div><canvas class="anno-canvas" id="annoCanvas"></canvas></div></div>`;renderTextWithHighlights(m.content||'',anns.filter(a=>a.type==='textHighlight'));setupCanvas(m,anns.filter(a=>a.type==='pen'||a.type==='freeHighlight'));captureSelection();restoreReaderPosition(m.id)}else if(m.type==='pdf'){await mountPdfReader(m)}else{activeObjectURL=URL.createObjectURL(m.blob);host.innerHTML=`<div class="unsupported"><h3>${esc(m.name)}</h3><p>This file is stored locally. Browser rendering is not available for this format.</p><a class="btn primary" href="${activeObjectURL}" download="${esc(m.name)}">Open / Download File</a></div>`}configureReaderInput()}

/* Text reader behavior retained for existing text materials. */
function renderTextWithHighlights(text,highlights){const root=document.getElementById('readerText');if(!root)return;const pts=new Set([0,text.length]);for(const h of highlights){pts.add(Math.max(0,h.start));pts.add(Math.min(text.length,h.end))}const sorted=[...pts].sort((a,b)=>a-b);let html='';for(let i=0;i<sorted.length-1;i++){const a=sorted[i],b=sorted[i+1],seg=text.slice(a,b);const h=[...highlights].reverse().find(x=>x.start<=a&&x.end>=b);html+=h?`<mark data-hid="${h.id}" style="background:${h.color};box-shadow:inset 0 -.85em rgba(0,0,0,0);background-color:${hexToRgba(h.color,h.opacity??.34)}">${esc(seg)}</mark>`:esc(seg)}root.innerHTML=html;root.querySelectorAll('mark').forEach(el=>el.onclick=e=>{e.stopPropagation();editTextHighlight(el.dataset.hid)})}
function hexToRgba(hex,a){let h=hex.replace('#','');if(h.length===3)h=h.split('').map(x=>x+x).join('');const n=parseInt(h,16);return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${a})`}
function captureSelection(){const root=document.getElementById('readerText');if(!root)return;root.addEventListener('mouseup',()=>saveSelection(root));root.addEventListener('touchend',()=>setTimeout(()=>saveSelection(root),50));}
function saveSelection(root){const sel=getSelection();if(!sel||sel.rangeCount===0||sel.isCollapsed)return;const r=sel.getRangeAt(0);if(!root.contains(r.commonAncestorContainer))return;const start=textOffset(root,r.startContainer,r.startOffset),end=textOffset(root,r.endContainer,r.endOffset);if(end>start)State.lastSelection={start,end,text:sel.toString()}}
function textOffset(root,node,offset){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let total=0,n;while(n=walker.nextNode()){if(n===node)return total+offset;total+=n.nodeValue.length}return total}
async function applyTextHighlight(){if(State.readerTool!=='textHighlight'||!State.lastSelection)return toast('Select some text first');const p=ReaderPrefs.get();const a={id:uid('ann'),topicId:State.topicId,materialId:State.materialId,type:'textHighlight',start:State.lastSelection.start,end:State.lastSelection.end,selectedText:State.lastSelection.text,color:p.hlColor,opacity:p.hlOpacity,createdAt:now()};await Storage.put('annotations',a);pushAction({type:'add',record:a});State.lastSelection=null;const m=await Storage.get('materials',State.materialId);await mountReaderContent(m);toast('Text highlighted')}
async function editTextHighlight(id){const a=await Storage.get('annotations',id);if(!a)return;openSheet('Text Highlight',`<div class="small muted">${esc(a.selectedText||'')}</div><div class="tool-settings" style="margin-top:10px">${['#ffe66d','#ffb3c7','#a7d8ff','#bdecc8','#d4b9ff','#ffc98b'].map(c=>`<button class="color-dot" style="background:${c}" onclick="recolorHighlight('${id}','${c}')"></button>`).join('')}</div>`,`<button class="btn danger" onclick="deleteAnnotation('${id}')">Delete Highlight</button><button class="btn" onclick="closeSheet()">Done</button>`)}
async function recolorHighlight(id,c){const a=await Storage.get('annotations',id);a.color=c;await Storage.put('annotations',a);closeSheet();const m=await Storage.get('materials',a.materialId);await mountReaderContent(m)}

/* Existing freehand canvas for text materials. */
let canvasCtx=null,canvasEl=null,drawing=false,currentStroke=null,canvasAnns=[];
function configureReaderInput(){if(canvasEl)canvasEl.style.pointerEvents=['pen','freeHighlight','eraser'].includes(State.readerTool)?'auto':'none';pdfConfigureReaderInput()}
async function setupCanvas(m,anns){canvasEl=document.getElementById('annoCanvas');if(!canvasEl)return;canvasAnns=anns;resizeCanvas();canvasCtx=canvasEl.getContext('2d');renderStrokes();configureReaderInput();canvasEl.onpointerdown=e=>startStroke(e,m);canvasEl.onpointermove=e=>moveStroke(e,m);canvasEl.onpointerup=e=>endStroke(e,m);canvasEl.onpointercancel=e=>endStroke(e,m);new ResizeObserver(()=>{resizeCanvas();renderStrokes()}).observe(document.getElementById('readerText'))}
function resizeCanvas(){const txt=document.getElementById('readerText');if(!canvasEl||!txt)return;const dpr=devicePixelRatio||1,w=txt.scrollWidth,h=txt.scrollHeight;canvasEl.style.width=w+'px';canvasEl.style.height=h+'px';canvasEl.width=Math.max(1,Math.floor(w*dpr));canvasEl.height=Math.max(1,Math.floor(h*dpr));canvasCtx=canvasEl.getContext('2d');canvasCtx.setTransform(dpr,0,0,dpr,0,0)}
function pointFromEvent(e){const r=canvasEl.getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top,p:e.pressure&&e.pressure>0?e.pressure:.5}}
function startStroke(e,m){if(State.readerTool==='eraser'){eraseAt(pointFromEvent(e));return}if(!['pen','freeHighlight'].includes(State.readerTool))return;e.preventDefault();canvasEl.setPointerCapture?.(e.pointerId);drawing=true;const p=ReaderPrefs.get(),pt=pointFromEvent(e);currentStroke={id:uid('ann'),topicId:m.topicId,materialId:m.id,type:State.readerTool,color:State.readerTool==='pen'?p.penColor:p.hlColor,thickness:State.readerTool==='pen'?p.penSize:p.hlSize,opacity:State.readerTool==='pen'?1:p.hlOpacity,straight:State.readerTool==='freeHighlight'?p.straight:false,points:[normPoint(pt)],createdAt:now()};}
function drawImmediateReaderSegment(s,a,b){if(!canvasCtx||!canvasEl||!s||!a||!b)return;const ax=a.x*canvasEl.clientWidth,ay=a.y*canvasEl.clientHeight,bx=b.x*canvasEl.clientWidth,by=b.y*canvasEl.clientHeight;canvasCtx.save();canvasCtx.globalAlpha=s.opacity??1;canvasCtx.strokeStyle=s.color;canvasCtx.lineCap='round';canvasCtx.lineJoin='round';canvasCtx.lineWidth=s.thickness;if(s.type==='freeHighlight')canvasCtx.globalCompositeOperation='source-over';canvasCtx.beginPath();canvasCtx.moveTo(ax,ay);canvasCtx.lineTo(bx,by);canvasCtx.stroke();canvasCtx.restore()}
