/* ----------------------------- PDF.js loader ----------------------------- */
const PDFJS_VERSION='3.11.174';
const PDFJS_CACHE_LIB=`pdfjs:${PDFJS_VERSION}:library`;
const PDFJS_CACHE_WORKER=`pdfjs:${PDFJS_VERSION}:worker`;
const PDFJS_CDNS=[
 {lib:`https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${PDFJS_VERSION}/pdf.min.js`,worker:`https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${PDFJS_VERSION}/pdf.worker.min.js`},
 {lib:`https://cdn.jsdelivr.net/npm/pdfjs-dist@${PDFJS_VERSION}/build/pdf.min.js`,worker:`https://cdn.jsdelivr.net/npm/pdfjs-dist@${PDFJS_VERSION}/build/pdf.worker.min.js`}
];
let pdfJsLoadPromise=null,pdfJsWorkerObjectURL=null;
async function fetchWithTimeout(url,ms=12000){const ctl=new AbortController(),tm=setTimeout(()=>ctl.abort(),ms);try{const r=await fetch(url,{mode:'cors',cache:'force-cache',signal:ctl.signal});if(!r.ok)throw new Error(`HTTP ${r.status}`);return await r.text()}finally{clearTimeout(tm)}}
async function injectScriptText(source){const u=URL.createObjectURL(new Blob([source],{type:'text/javascript'}));try{await new Promise((res,rej)=>{const sc=document.createElement('script');sc.src=u;sc.onload=()=>{sc.remove();res()};sc.onerror=()=>{sc.remove();rej(new Error('PDF engine script could not be started'))};document.head.appendChild(sc)})}finally{URL.revokeObjectURL(u)}}
