function setupPdfScrollTracking(){const sc=document.getElementById('pdfScroll');if(!sc)return;sc.addEventListener('scroll',()=>{if(PdfReader.scrollRaf)return;PdfReader.scrollRaf=requestAnimationFrame(()=>{PdfReader.scrollRaf=0;pdfUpdateCurrentPageFromScroll()})},{passive:true});pdfUpdateCurrentPageFromScroll()}
function pdfUpdateCurrentPageFromScroll(){const sc=document.getElementById('pdfScroll');if(!sc)return;const target=sc.scrollTop+Math.min(sc.clientHeight*.28,220);let best=PdfReader.pageNumber,bestDist=Infinity;for(const el of sc.querySelectorAll('.pdf-page-wrap')){const d=Math.abs((el.offsetTop+20)-target);if(d<bestDist){bestDist=d;best=+el.dataset.page}}if(best!==PdfReader.pageNumber){PdfReader.pageNumber=best;const inp=document.getElementById('pdfPageInput');if(inp)inp.value=best;pdfSaveReaderState();pdfMarkSearchPages()}trimPdfRenderedPages(best)}
function pdfSaveReaderState(){if(!PdfReader.materialId)return;const id=PdfReader.materialId,value={page:PdfReader.pageNumber,fitMode:PdfReader.fitMode,zoom:PdfReader.zoom,lastStudied:now()};StudyDataSafety.debounce('pdf-position:'+id,()=>setMeta('pdfReader:'+id,value),300)}
function setupPdfResizeObserver(){const sc=document.getElementById('pdfScroll');if(!sc||!window.ResizeObserver)return;PdfReader.lastWidth=sc.clientWidth;PdfReader.resizeObserver=new ResizeObserver(()=>{if(!PdfReader.active()||PdfReader.fitMode==='custom')return;const w=sc.clientWidth;if(Math.abs(w-PdfReader.lastWidth)<4)return;PdfReader.lastWidth=w;if(PdfReader.drawing||PdfReader.erasing){PdfReader.pendingRelayout=true;return}clearTimeout(PdfReader.resizeTimer);PdfReader.resizeTimer=setTimeout(()=>pdfRelayoutContinuous().catch(e=>showPdfError(PdfReader.material,e)),180)});PdfReader.resizeObserver.observe(sc)}
