function unrenderPdfPage(pageNo){if(PdfReader.activePage===pageNo&&PdfReader.drawing)return;for(const id of ['pdfCanvas-','pdfAnnoCanvas-','pdfLiveCanvas-']){const c=document.getElementById(id+pageNo);if(c){c.width=1;c.height=1}}const loading=document.getElementById('pdfPageLoading-'+pageNo);if(loading)loading.style.display='flex';PdfReader.renderedPages.delete(pageNo)}
function trimPdfRenderedPages(center){if(PdfReader.drawing||PdfReader.erasing)return;if(PdfReader.renderedPages.size<=12)return;const keep=[...PdfReader.renderedPages].sort((a,b)=>Math.abs(a-center)-Math.abs(b-center)).slice(0,10),set=new Set(keep);for(const n of [...PdfReader.renderedPages])if(!set.has(n))unrenderPdfPage(n)}
function pdfGoPage(n,smooth=true){if(!PdfReader.doc)return;const v=Math.max(1,Math.min(PdfReader.totalPages,Math.round(Number(n)||1))),wrap=document.getElementById('pdfPageWrap-'+v),sc=document.getElementById('pdfScroll');PdfReader.pageNumber=v;const inp=document.getElementById('pdfPageInput');if(inp)inp.value=v;renderPdfPage(v).catch(e=>showPdfError(PdfReader.material,e));if(wrap&&sc)sc.scrollTo({top:Math.max(0,wrap.offsetTop-8),behavior:smooth?'smooth':'auto'});pdfSaveReaderState()}
function pdfPrevPage(){pdfGoPage(PdfReader.pageNumber-1)}function pdfNextPage(){pdfGoPage(PdfReader.pageNumber+1)}
function pdfSetFit(mode,value){if(!PdfReader.doc)return;PdfReader.fitMode=mode==='custom'?'custom':'width';if(PdfReader.fitMode==='custom')PdfReader.zoom=Math.max(.25,Math.min(4,+value||1));pdfRelayoutContinuous().catch(e=>showPdfError(PdfReader.material,e))}
function pdfZoomBy(factor){if(!PdfReader.doc)return;const metric=PdfReader.pageMetrics.get(PdfReader.pageNumber);const current=PdfReader.fitMode==='custom'?PdfReader.zoom:(metric?.scale||1);PdfReader.zoom=Math.max(.25,Math.min(4,current*factor));PdfReader.fitMode='custom';pdfRelayoutContinuous().catch(e=>showPdfError(PdfReader.material,e))}

/* PDF text search uses PDF.js extraction and jumps by scrolling to matching pages. */
async function pdfPageText(n){if(PdfReader.textCache.has(n))return PdfReader.textCache.get(n);const p=await PdfReader.doc.getPage(n),tc=await p.getTextContent(),text=tc.items.map(x=>x.str||'').join(' ');PdfReader.textCache.set(n,text);return text}
function pdfSearchKey(e){if(e.key==='Enter'){e.preventDefault();if(PdfReader.searchResults.length&&(e.shiftKey||document.getElementById('pdfSearchInput').value.trim()===PdfReader.lastSearch))pdfSearchStep(e.shiftKey?-1:1);else pdfSearch()}}
async function pdfSearch(){if(!PdfReader.doc)return;const input=document.getElementById('pdfSearchInput'),q=(input?.value||'').trim();PdfReader.lastSearch=q;const token=++PdfReader.searchToken;PdfReader.searchResults=[];PdfReader.searchIndex=-1;updatePdfSearchCount();if(!q){pdfMarkSearchPages();return}setPdfStatus('Searching PDF…');const needle=q.toLocaleLowerCase();for(let page=1;page<=PdfReader.totalPages;page++){if(token!==PdfReader.searchToken)return;try{const original=await pdfPageText(page),text=original.toLocaleLowerCase();let from=0;while((from=text.indexOf(needle,from))!==-1){PdfReader.searchResults.push({page,start:from,length:needle.length,count:1,snippet:original.slice(Math.max(0,from-35),from+needle.length+60)});from+=Math.max(1,needle.length)}}catch(e){console.warn('PDF text extraction failed on page',page,e)}if(page%4===0)await new Promise(r=>setTimeout(r,0))}if(token!==PdfReader.searchToken)return;setPdfStatus('');if(PdfReader.searchResults.length){PdfReader.searchIndex=0;updatePdfSearchCount();pdfMarkSearchPages();pdfGoPage(PdfReader.searchResults[0].page)}else{updatePdfSearchCount();pdfMarkSearchPages();toast('No PDF search matches')}}
function updatePdfSearchCount(){const e=document.getElementById('pdfSearchCount');if(!e)return;if(!PdfReader.lastSearch){e.textContent='';return}const total=PdfReader.searchResults.length,result=PdfReader.searchResults[PdfReader.searchIndex];e.textContent=total?`${PdfReader.searchIndex+1} / ${total} results · page ${result?.page||''}`:'No matches';e.title=result?.snippet||'';e.setAttribute('aria-live','polite')}
function pdfSearchStep(dir){if(!PdfReader.searchResults.length)return pdfSearch();PdfReader.searchIndex=(PdfReader.searchIndex+dir+PdfReader.searchResults.length)%PdfReader.searchResults.length;updatePdfSearchCount();pdfMarkSearchPages();pdfGoPage(PdfReader.searchResults[PdfReader.searchIndex].page);toast(PdfReader.searchResults[PdfReader.searchIndex].snippet)}
