StudyDataSafety.install(Storage);
window.studyBaseReady=(async function boot(){try{await Storage.init();await ensureRequestedCourseSubjects();await ensureBundledStudyModules();updateNetwork();renderNav();await render();}catch(e){document.getElementById('main').innerHTML=`<div class="card"><h2>Storage could not start</h2><p class="muted">${esc(e.message||e)}</p><p class="muted small">Allow site storage in a regular Chrome or Samsung Internet window. Your database has not been cleared. Export from your original working app if recovery is needed.</p></div>`}})();
